const BONUS_THRESHOLD = 3;
const BASE_SCORE = 2;
const POINTS_PER_BONUS_TYPE = 2;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  const types = countNonSphinxTypes(army);
  if (types <= BONUS_THRESHOLD) return BASE_SCORE;
  const bonusTypes = types - BONUS_THRESHOLD;
  return BASE_SCORE - 1 + POINTS_PER_BONUS_TYPE * bonusTypes;
};

